// Mounted panels are shared with the phone pages. Switching only changes
// visibility: no duplicate controllers, reads, forms, or transaction paths.
import { subscribePendingActions, subscribePendingActionErrors, reportPendingActionError } from './pending-actions.js';
import { briefTxError } from './ui-error.js';
export const INFO_ROTATE_MS = 30_000;
const ORDER = ['pending', 'tickets', 'bounties', 'quests', 'referrals', 'afking', 'deity', 'tokens', 'decimator', 'baf'];
const LABELS = { pending: 'Pending', tickets: 'Tickets', bounties: 'Bounties', quests: 'Quests',
  referrals: 'Refer friends', afking: 'AFKing', deity: 'Deity', tokens: 'Tokens', decimator: 'Decimator', baf: 'BAF' };
const desktop = window.matchMedia('(min-width: 1100px)');
const body = document.body;
const rail = document.querySelector('.info-rail');
const track = rail?.querySelector('.info-rail__track');
const tabs = rail?.querySelector('[data-info-tabs]');
const tabButtons = new Map();
let current = 'quests';
// Event availability arrives asynchronously. Prefer an active event during
// startup, then leave navigation alone after the first rotation or interaction.
let choosingStart = true;
let revealed = false;
let preparingSlide = null;
let held = false;
let available = [];
let timer;
let refreshing = false;
let miningAction = null;
let miningBusy = false;
let pendingActive = false;
let pendingItemCount = 0;
const referralStrip = rail?.querySelector('[data-referral-strip]');
const referralHome = referralStrip ? document.createComment('Referral banner home') : null;
let referralSlide = null;

if (tabs) {
  for (const name of ORDER) {
    const button = document.createElement('button');
    button.type = 'button';
    button.dataset.infoTab = name;
    button.textContent = LABELS[name];
    button.hidden = true;
    tabs.append(button);
    tabButtons.set(name, button);
  }
}

if (referralStrip && track) {
  referralStrip.before(referralHome);
  referralSlide = document.createElement('section');
  referralSlide.className = 'info-referral-slot play-grid';
  referralSlide.dataset.infoSlide = 'referrals';
  referralSlide.setAttribute('aria-label', 'Refer friends');
  referralSlide.hidden = true;
  const content = document.createElement('div');
  content.className = 'quest-hub';
  referralSlide.append(content);
  track.append(referralSlide);
}

function syncReferral() {
  if (!referralSlide) return;
  const destination = enabled() ? referralSlide.firstElementChild : referralHome.parentNode;
  if (referralStrip.parentNode !== destination) {
    if (enabled()) destination.append(referralStrip);
    else referralHome.after(referralStrip);
  }
  const hidden = !enabled() || referralStrip.hidden || !referralStrip.childElementCount;
  if (referralSlide.hidden !== hidden) referralSlide.hidden = hidden;
}

function referralFitsQuests() {
  return track?.clientWidth >= 1280
    && !panel('quests')?.querySelector('app-parimutuel-panel[data-growth-bettable="true"]');
}

function enabled() { return Boolean(rail && desktop.matches && body.dataset.desktopPage); }
function panel(name) { return rail?.querySelector(`[data-info-slide="${name}"]`); }
function publish() { document.dispatchEvent(new CustomEvent('desktop-info:change', { detail: { slide: current } })); }
function readyHost(name) {
  const slide = panel(name);
  return name === 'quests' ? slide?.querySelector('app-quest-panel') || slide : slide;
}
function firstPanelReady() {
  // A slow unrelated event must not hide a usable opening panel. Event
  // availability can still select BAF/Decimator until the first interaction.
  const host = readyHost(current);
  const ready = host?.getAttribute('data-info-ready');
  return ready === 'true' || (ready == null && Boolean(host?.childElementCount));
}
function revealWhenReady() {
  rail.classList.toggle('is-info-ready', revealed);
  rail.inert = false;
  rail.removeAttribute('aria-hidden');
  if (enabled() && !revealed) {
    rail.setAttribute('aria-busy', 'true');
  } else {
    rail.removeAttribute('aria-busy');
    rail.removeAttribute('aria-hidden');
  }
  if (!enabled() || revealed || !firstPanelReady() || preparingSlide === current) return;
  const opening = current;
  preparingSlide = opening;
  const images = [...panel(opening).querySelectorAll('img')]
    .filter(img => img.getClientRects().length && getComputedStyle(img).visibility !== 'hidden');
  // Only the opening panel's visible artwork participates. Other panels keep
  // loading independently; a broken image cannot hold the controls hostage.
  for (const img of images) img.loading = 'eager';
  // Artwork is decorative. Give cached images one frame, but never make a
  // slow download a prerequisite for scores, navigation, or the Mine button.
  Promise.race([
    Promise.allSettled(images.map(img => img.decode?.())),
    new Promise(resolve => setTimeout(resolve, 120)),
  ]).then(() => {
    requestAnimationFrame(() => {
      if (preparingSlide !== opening) return;
      preparingSlide = null;
      if (!enabled() || current !== opening || !firstPanelReady()) return;
      revealed = true;
      paint();
      schedule();
    });
  });
}

function paint() {
  body.dataset.desktopInfo = current;
  const companion = enabled() && referralSlide && !referralSlide.hidden
    && ((current === 'quests' && referralFitsQuests())
      || (current === 'pending' && pendingItemCount <= 2
        && track.clientWidth >= (pendingItemCount > 1 ? 1050 : 800)));
  body.dataset.desktopReferralCompanion = companion ? current : '';
  for (const name of ORDER) {
    const slide = panel(name);
    const button = tabButtons.get(name);
    if (button) {
      button.hidden = !available.includes(name);
      if (current === name) button.setAttribute('aria-current', 'true');
      else button.removeAttribute('aria-current');
      if (slide) {
        slide.id ||= `info-panel-${name}`;
        button.setAttribute('aria-controls', slide.id);
      }
    }
    if (!slide) continue;
    const active = current === name || (name === 'referrals' && companion);
    slide.classList.toggle('is-info-available', available.includes(name) || active);
    slide.classList.toggle('is-info-active', active);
    slide.inert = enabled() && !active;
    if (enabled() && !active) slide.setAttribute('aria-hidden', 'true');
    else slide.removeAttribute('aria-hidden');
  }
  for (const arrow of rail.querySelectorAll('[data-info-step]')) arrow.disabled = available.length < 2;
  revealWhenReady();
}
function hold() { if (enabled()) { choosingStart = false; held = true; clearTimeout(timer); } }
function schedule() {
  clearTimeout(timer);
  if (!enabled() || !revealed || held || document.hidden || miningBusy || available.length < 2) return;
  timer = setTimeout(() => {
    const modal = [...document.querySelectorAll('dialog:modal, [aria-modal="true"]')]
      .some(el => !el.hidden && el.getClientRects().length > 0);
    if (!modal) select(available[(available.indexOf(current) + 1) % available.length]);
    schedule();
  }, INFO_ROTATE_MS);
}
function select(name) {
  if (!enabled() || !available.includes(name)) return;
  choosingStart = false;
  const changed = current !== name;
  current = name;
  paint();
  if (changed) publish();
  schedule();
}
export function showDesktopInfo(name) { select(name); }
function refresh() {
  refreshing = false;
  syncReferral();
  const next = ORDER.filter(name => {
    const el = panel(name);
    if (!el || el.hidden || (name === 'pending' && !pendingActive)) return false;
    // Referrals share wide quests only while Growth is unavailable. Otherwise
    // they keep their own carousel tab and leave room for the betting controls.
    if (name === 'referrals' && referralFitsQuests()) return false;
    if (name === 'deity') {
      const desk = el.querySelector('[data-bind="deity-desk"]');
      return desk && !desk.hidden;
    }
    return true;
  });
  const changed = next.join() !== available.join();
  available = next;
  const previous = current;
  if ((choosingStart && enabled()) || !available.includes(current)) {
    current = ['decimator', 'baf', 'quests', 'tickets'].find(name => available.includes(name)) || available[0];
  }
  paint();
  if (changed || previous !== current) { publish(); schedule(); }
}
if (rail && track) {
  const mine = rail.querySelector('[data-mine-flip]');
  const paintMining = () => {
    if (!mine) return;
    const busy = miningBusy || miningAction?.state === 'busy';
    const ready = !busy && miningAction?.state === 'ready' && typeof miningAction.run === 'function';
    mine.disabled = !ready;
    mine.dataset.state = busy ? 'busy' : ready ? 'ready' : 'idle';
    mine.setAttribute('aria-busy', String(busy));
    const label = busy ? 'Mining FLIP' : ready ? 'Mine FLIP — mining available' : 'Mine FLIP — no work available';
    mine.setAttribute('aria-label', label);
    mine.title = label;
    mine.querySelector('span').textContent = busy ? 'MINING…' : 'MINE FLIP';
  };
  subscribePendingActions(items => {
    miningAction = items.find(item => item.id?.startsWith('mine-flip:')) || null;
    paintMining();
  });
  mine?.addEventListener('click', async () => {
    if (miningBusy || miningAction?.state !== 'ready' || typeof miningAction.run !== 'function') return;
    const action = miningAction;
    miningBusy = true;
    paintMining();
    schedule();
    try { await action.run(); }
    catch (error) { reportPendingActionError(briefTxError(error, 'Could not mine FLIP. Try again.')); }
    finally { miningBusy = false; paintMining(); schedule(); }
  });
  const feedback = rail.querySelector('.info-rail__feedback');
  let feedbackTimer;
  subscribePendingActionErrors(message => {
    if (!feedback) return;
    clearTimeout(feedbackTimer);
    feedback.textContent = message;
    feedback.hidden = !message;
    feedbackTimer = setTimeout(() => { feedback.hidden = true; }, 10_000);
  });
  const paintPending = summary => {
    // Mine FLIP has its own permanent button; it cannot create an empty slide.
    const items = (summary?.items || []).filter(item => item.kind !== 'mass-resolution');
    pendingItemCount = items.length;
    const next = items.length > 0 || Boolean(summary?.rng);
    panel('pending')?.classList.toggle('has-pending-items', next);
    if (next !== pendingActive) { pendingActive = next; refresh(); }
    else paint();
  };
  document.addEventListener('app-reveal-tray:summary', event => paintPending(event.detail));
  paintPending(panel('pending')?.pendingSummary);
  refresh();
  rail.addEventListener('click', event => {
    const tab = event.target.closest('[data-info-tab]');
    if (tab && available.includes(tab.dataset.infoTab)) { hold(); select(tab.dataset.infoTab); return; }
    const step = event.target.closest('[data-info-step]');
    if (!step || !available.length) return;
    hold();
    select(available[(available.indexOf(current) + Number(step.dataset.infoStep) + available.length) % available.length]);
  });
  // Reading the banner does not stop rotation; working with it does. Focus
  // covers keyboard users, and pointerdown preserves an in-progress edit.
  track.addEventListener('pointerdown', hold, { passive: true });
  track.addEventListener('focusin', hold);
  // Purchase/game badges open the same quest dialog from outside the banner.
  // Reveal its owning slide before the quest controller handles the event.
  document.addEventListener('quest:open', () => {
    if (enabled()) { hold(); select('quests'); }
  }, true);
  document.addEventListener('visibilitychange', schedule);
  desktop.addEventListener('change', () => { refresh(); schedule(); });
  document.addEventListener('desktop-sections:change', () => { refresh(); schedule(); });
  if (typeof ResizeObserver === 'function') new ResizeObserver(refresh).observe(track);
  new MutationObserver(() => {
    if (!refreshing) { refreshing = true; requestAnimationFrame(refresh); }
  }).observe(track, { subtree: true, childList: true, attributes: true, attributeFilter: ['hidden', 'data-info-ready', 'data-growth-bettable'] });
  const nativeScrollIntoView = Element.prototype.scrollIntoView;
  Element.prototype.scrollIntoView = function scrollIntoBanner(...args) {
    const slide = this.closest('[data-info-slide]');
    if (enabled() && slide && rail.contains(slide)) { hold(); select(slide.dataset.infoSlide); }
    return nativeScrollIntoView.apply(this, args);
  };
  schedule();
}
